-- A1 — the pick: a draft carries no picker; a picked or dispatched RTV
-- carries all three; a cancelled one carries all three or none (cancelled
-- after a pick, or before). Written as implications plus "all or none", so
-- an unknown status is refused by the status CHECK alone.
ALTER TABLE "vendor_returns" ADD CONSTRAINT "vendor_returns_picked_pairing" CHECK (
	("status" <> 'draft' OR ("picked_by" IS NULL AND "picked_at" IS NULL AND "picked_device_id" IS NULL))
	AND ("status" NOT IN ('picked', 'dispatched') OR ("picked_by" IS NOT NULL AND "picked_at" IS NOT NULL AND "picked_device_id" IS NOT NULL))
	AND ("picked_by" IS NULL) = ("picked_at" IS NULL)
	AND ("picked_at" IS NULL) = ("picked_device_id" IS NULL)
);--> statement-breakpoint
-- A1 — the dispatch: a dispatched RTV carries the dispatcher, the instant,
-- the brand document (type, number, date) and the package count; no other
-- status carries any dispatch column at all.
ALTER TABLE "vendor_returns" ADD CONSTRAINT "vendor_returns_dispatch_pairing" CHECK (
	("status" = 'dispatched'
		AND "dispatched_by" IS NOT NULL AND "dispatched_at" IS NOT NULL
		AND "brand_document_type" IS NOT NULL AND "brand_document_number" IS NOT NULL
		AND "brand_document_date" IS NOT NULL AND "package_count" IS NOT NULL)
	OR ("status" <> 'dispatched'
		AND "dispatched_by" IS NULL AND "dispatched_at" IS NULL
		AND "brand_document_type" IS NULL AND "brand_document_number" IS NULL
		AND "brand_document_date" IS NULL AND "package_count" IS NULL
		AND "eway_bill_number" IS NULL AND "eway_bill_date" IS NULL AND "eway_valid_until" IS NULL
		AND "debit_note_number" IS NULL AND "consignor_gstin" IS NULL
		AND "transporter_id" IS NULL AND "transporter_snapshot" IS NULL
		AND "carrier_name" IS NULL AND "tracking_ref" IS NULL AND "vehicle_number" IS NULL
		AND "warehouse_snapshot" IS NULL)
);--> statement-breakpoint
ALTER TABLE "vendor_returns" ADD CONSTRAINT "vendor_returns_transporter_pairing" CHECK (
	("transporter_id" IS NULL) = ("transporter_snapshot" IS NULL)
);--> statement-breakpoint
-- A1 — the cancel: a cancelled RTV carries the canceller, the instant and
-- the reason; nothing else carries any of them.
ALTER TABLE "vendor_returns" ADD CONSTRAINT "vendor_returns_cancel_pairing" CHECK (
	("status" = 'cancelled') = ("cancelled_by" IS NOT NULL AND "cancelled_at" IS NOT NULL AND "cancel_reason" IS NOT NULL)
	AND ("cancelled_by" IS NULL) = ("cancelled_at" IS NULL)
	AND ("cancelled_at" IS NULL) = ("cancel_reason" IS NULL)
