-- ── the post-migration assertion (the 0064/0091 model) ────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction — a valid
-- base row, then the one change under test — and must be refused BY ITS
-- NAMED CONSTRAINT (guide §3, CHECKs in name order).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	v uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	d uuid := gen_random_uuid();
	r uuid;
	refused_by text;
	expected text;
	probe text;
	base text;
BEGIN
	IF NOT (SELECT relrowsecurity FROM pg_class WHERE relname = 'vendor_returns')
		OR NOT (SELECT relrowsecurity FROM pg_class WHERE relname = 'vendor_return_lines') THEN
		RAISE EXCEPTION 'migration 0105: row level security is not enabled on the new tables.';
	END IF;
	-- (1) accepted shapes: a draft, a picked, a dispatched (with an e-way
	-- bill, a transporter and a vehicle), a draft cancelled, a picked RTV
	-- cancelled, and lines — untracked, batch, sourced, picked short and 0.
	BEGIN
		r := gen_random_uuid();
		INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","note","created_by")
		VALUES (r, t, w, c, v, 'RTV-P001', 'draft', 'dispatch', '{}', '{}', 'probe', u);
		INSERT INTO "vendor_return_lines" ("id","tenant_id","vendor_return_id","line_no","sku_id","batch_id","grn_line_id","qty","picked_qty","reason_code","item_snapshot")
		VALUES (gen_random_uuid(), t, r, 1, gen_random_uuid(), NULL, NULL, 1, NULL, 'damaged', '{}'),
		       (gen_random_uuid(), t, r, 2, c, d, NULL, 6000, NULL, 'quality-failure', '{}'),
		       (gen_random_uuid(), t, r, 3, c, d, u, 4000, NULL, 'other', '{}');
		INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","created_by","picked_by","picked_at","picked_device_id")
		VALUES (gen_random_uuid(), t, w, c, v, 'RTV-P002', 'picked', 'registered', '{}', '{}', u, u, now(), d);
		r := gen_random_uuid();
		INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","created_by","picked_by","picked_at","picked_device_id",
			"dispatched_by","dispatched_at","brand_document_type","brand_document_number","brand_document_date","consignor_gstin","debit_note_number","eway_bill_number","eway_bill_date","eway_valid_until",
			"transporter_id","transporter_snapshot","carrier_name","tracking_ref","vehicle_number","package_count","warehouse_snapshot")
		VALUES (r, t, w, c, v, 'RTV-P003', 'dispatched', 'dispatch', '{}', '{}', u, u, now(), d,
			u, now(), 'challan', 'CH-77', current_date, '29ABCDE1234F1Z5', 'DN-9', '123456789012', current_date, current_date + 1,
			v, '{}', 'BlueDart', 'AWB1234', 'KA01AB1234', 9999, '{}');
		INSERT INTO "vendor_return_lines" ("id","tenant_id","vendor_return_id","line_no","sku_id","batch_id","grn_line_id","qty","picked_qty","reason_code","item_snapshot")
		VALUES (gen_random_uuid(), t, r, 1, c, NULL, NULL, 6000, 4000, 'expired', '{}'),
		       (gen_random_uuid(), t, r, 2, v, NULL, NULL, 2000, 0, 'recall', '{}'),
		       (gen_random_uuid(), t, r, 200, u, NULL, NULL, 2000, 2000, 'wrong-item', '{}');
		INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","created_by","cancelled_by","cancelled_at","cancel_reason")
		VALUES (gen_random_uuid(), t, w, c, v, 'RTV-P004', 'cancelled', 'dispatch', '{}', '{}', u, u, now(), 'cancel a draft');
		INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","created_by","picked_by","picked_at","picked_device_id","cancelled_by","cancelled_at","cancel_reason")
		VALUES (gen_random_uuid(), t, w, c, v, 'RTV-P005', 'cancelled', 'dispatch', '{}', '{}', u, u, now(), d, u, now(), 'cancel a picked RTV');
		RAISE EXCEPTION USING ERRCODE = 'P0105', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0105: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0105' THEN
			NULL;
	END;
	-- (2) refused shapes: a base row of the named status, then one change.
	FOREACH probe IN ARRAY ARRAY[
		'unknown status', 'unknown address kind', 'unknown brand document type',
		'draft with a picker', 'picked without a device', 'cancelled with half a picker',
		'dispatched without a package count', 'draft with a tracking ref', 'draft with a brand document',
		'transporter without its snapshot', 'cancelled without a reason', 'draft with a canceller',
		'dispatched with no carrier', 'zero packages', 'malformed e-way bill', 'lowercase vehicle',
		'e-way bill without a date', 'validity before the e-way date', 'overlong note',
		'malformed consignor GSTIN', 'overlong brand document number', 'validity without an e-way bill',
		'overlong cancel reason', 'cancelled missing only its reason',
		'zero line qty', 'picked above the line', 'negative picked', 'unknown reason', 'line 0',
		'duplicate arm', 'duplicate line number'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown status' THEN 'vendor_returns_status_check'
			WHEN 'unknown address kind' THEN 'vendor_returns_consignee_address_kind_check'
			WHEN 'unknown brand document type' THEN 'vendor_returns_brand_document_type_check'
			WHEN 'draft with a picker' THEN 'vendor_returns_picked_pairing'
			WHEN 'picked without a device' THEN 'vendor_returns_picked_pairing'
			WHEN 'cancelled with half a picker' THEN 'vendor_returns_picked_pairing'
			WHEN 'dispatched without a package count' THEN 'vendor_returns_dispatch_pairing'
			WHEN 'draft with a tracking ref' THEN 'vendor_returns_dispatch_pairing'
			WHEN 'draft with a brand document' THEN 'vendor_returns_dispatch_pairing'
			WHEN 'transporter without its snapshot' THEN 'vendor_returns_transporter_pairing'
			WHEN 'cancelled without a reason' THEN 'vendor_returns_cancel_pairing'
			WHEN 'draft with a canceller' THEN 'vendor_returns_cancel_pairing'
			WHEN 'dispatched with no carrier' THEN 'vendor_returns_carrier_identity'
			WHEN 'zero packages' THEN 'vendor_returns_capture_format'
			WHEN 'malformed e-way bill' THEN 'vendor_returns_capture_format'
			WHEN 'lowercase vehicle' THEN 'vendor_returns_capture_format'
			WHEN 'e-way bill without a date' THEN 'vendor_returns_eway_pairing'
			WHEN 'validity before the e-way date' THEN 'vendor_returns_eway_pairing'
			WHEN 'overlong note' THEN 'vendor_returns_note_length'
			WHEN 'malformed consignor GSTIN' THEN 'vendor_returns_capture_format'
			WHEN 'overlong brand document number' THEN 'vendor_returns_capture_format'
			WHEN 'validity without an e-way bill' THEN 'vendor_returns_eway_pairing'
			WHEN 'overlong cancel reason' THEN 'vendor_returns_note_length'
			WHEN 'cancelled missing only its reason' THEN 'vendor_returns_cancel_pairing'
			WHEN 'zero line qty' THEN 'vendor_return_lines_qty_positive'
			WHEN 'picked above the line' THEN 'vendor_return_lines_picked_range'
			WHEN 'negative picked' THEN 'vendor_return_lines_picked_range'
			WHEN 'unknown reason' THEN 'vendor_return_lines_reason_check'
			WHEN 'line 0' THEN 'vendor_return_lines_line_no_positive'
			WHEN 'duplicate arm' THEN 'vendor_return_lines_arm_unique'
			ELSE 'vendor_return_lines_line_no_unique'
		END;
		base := CASE
			WHEN probe IN ('picked without a device') THEN 'picked'
			WHEN probe IN ('cancelled with half a picker') THEN 'cancelled-picked'
			WHEN probe IN ('cancelled without a reason', 'overlong cancel reason', 'cancelled missing only its reason') THEN 'cancelled'
			WHEN probe IN ('unknown brand document type', 'dispatched without a package count', 'transporter without its snapshot',
				'dispatched with no carrier', 'zero packages', 'malformed e-way bill', 'lowercase vehicle',
				'e-way bill without a date', 'validity before the e-way date', 'malformed consignor GSTIN',
				'overlong brand document number', 'validity without an e-way bill') THEN 'dispatched'
			ELSE 'draft'
		END;
		BEGIN
			r := gen_random_uuid();
			INSERT INTO "vendor_returns" ("id","tenant_id","warehouse_id","client_id","vendor_id","code","status","consignee_address_kind","vendor_snapshot","client_snapshot","created_by")
			VALUES (r, t, w, c, v, 'RTV-R' || r::text, 'draft', 'dispatch', '{}', '{}', u);
			IF base IN ('picked', 'cancelled-picked', 'dispatched') THEN
				UPDATE "vendor_returns" SET "status" = 'picked', "picked_by" = u, "picked_at" = now(), "picked_device_id" = d WHERE "id" = r;
			END IF;
			IF base = 'dispatched' THEN
				UPDATE "vendor_returns" SET "status" = 'dispatched', "dispatched_by" = u, "dispatched_at" = now(),
					"brand_document_type" = 'challan', "brand_document_number" = 'CH-1', "brand_document_date" = current_date,
					"package_count" = 1, "carrier_name" = 'BlueDart', "warehouse_snapshot" = '{}' WHERE "id" = r;
			END IF;
			IF base IN ('cancelled', 'cancelled-picked') THEN
				UPDATE "vendor_returns" SET "status" = 'cancelled', "cancelled_by" = u, "cancelled_at" = now(), "cancel_reason" = 'probe' WHERE "id" = r;
			END IF;
			IF probe IN ('zero line qty', 'picked above the line', 'negative picked', 'unknown reason', 'line 0', 'duplicate arm', 'duplicate line number') THEN
				INSERT INTO "vendor_return_lines" ("id","tenant_id","vendor_return_id","line_no","sku_id","batch_id","grn_line_id","qty","picked_qty","reason_code","item_snapshot")
				VALUES (gen_random_uuid(), t, r, 1, c, NULL, NULL, 2000, NULL, 'damaged', '{}');
			END IF;
			CASE probe
				WHEN 'unknown status' THEN UPDATE "vendor_returns" SET "status" = 'lost' WHERE "id" = r;
				WHEN 'unknown address kind' THEN UPDATE "vendor_returns" SET "consignee_address_kind" = 'home' WHERE "id" = r;
				WHEN 'unknown brand document type' THEN UPDATE "vendor_returns" SET "brand_document_type" = 'debit_note' WHERE "id" = r;
				WHEN 'draft with a picker' THEN UPDATE "vendor_returns" SET "picked_by" = u, "picked_at" = now(), "picked_device_id" = d WHERE "id" = r;
				WHEN 'picked without a device' THEN UPDATE "vendor_returns" SET "picked_device_id" = NULL WHERE "id" = r;
				WHEN 'cancelled with half a picker' THEN UPDATE "vendor_returns" SET "picked_device_id" = NULL WHERE "id" = r;
				WHEN 'dispatched without a package count' THEN UPDATE "vendor_returns" SET "package_count" = NULL WHERE "id" = r;
				WHEN 'draft with a tracking ref' THEN UPDATE "vendor_returns" SET "tracking_ref" = 'AWB1' WHERE "id" = r;
				WHEN 'draft with a brand document' THEN UPDATE "vendor_returns" SET "brand_document_type" = 'challan' WHERE "id" = r;
				WHEN 'transporter without its snapshot' THEN UPDATE "vendor_returns" SET "transporter_id" = v WHERE "id" = r;
				WHEN 'cancelled without a reason' THEN UPDATE "vendor_returns" SET "cancel_reason" = NULL, "cancelled_at" = NULL, "cancelled_by" = NULL WHERE "id" = r;
				WHEN 'draft with a canceller' THEN UPDATE "vendor_returns" SET "cancelled_by" = u, "cancelled_at" = now(), "cancel_reason" = 'x' WHERE "id" = r;
				WHEN 'dispatched with no carrier' THEN UPDATE "vendor_returns" SET "carrier_name" = NULL WHERE "id" = r;
				WHEN 'zero packages' THEN UPDATE "vendor_returns" SET "package_count" = 0 WHERE "id" = r;
				WHEN 'malformed e-way bill' THEN UPDATE "vendor_returns" SET "eway_bill_number" = '12345', "eway_bill_date" = current_date WHERE "id" = r;
				WHEN 'lowercase vehicle' THEN UPDATE "vendor_returns" SET "vehicle_number" = 'ka01ab1234' WHERE "id" = r;
				WHEN 'e-way bill without a date' THEN UPDATE "vendor_returns" SET "eway_bill_number" = '123456789012' WHERE "id" = r;
				WHEN 'validity before the e-way date' THEN UPDATE "vendor_returns" SET "eway_bill_number" = '123456789012', "eway_bill_date" = current_date, "eway_valid_until" = current_date - 1 WHERE "id" = r;
				WHEN 'overlong note' THEN UPDATE "vendor_returns" SET "note" = repeat('x', 501) WHERE "id" = r;
				WHEN 'malformed consignor GSTIN' THEN UPDATE "vendor_returns" SET "consignor_gstin" = '29abcde1234f1z5' WHERE "id" = r;
				WHEN 'overlong brand document number' THEN UPDATE "vendor_returns" SET "brand_document_number" = repeat('C', 41) WHERE "id" = r;
				WHEN 'validity without an e-way bill' THEN UPDATE "vendor_returns" SET "eway_valid_until" = current_date WHERE "id" = r;
				WHEN 'overlong cancel reason' THEN UPDATE "vendor_returns" SET "cancel_reason" = repeat('x', 501) WHERE "id" = r;
				WHEN 'cancelled missing only its reason' THEN UPDATE "vendor_returns" SET "cancel_reason" = NULL WHERE "id" = r;
				WHEN 'zero line qty' THEN UPDATE "vendor_return_lines" SET "qty" = 0 WHERE "vendor_return_id" = r;
				WHEN 'picked above the line' THEN UPDATE "vendor_return_lines" SET "picked_qty" = 2001 WHERE "vendor_return_id" = r;
				WHEN 'negative picked' THEN UPDATE "vendor_return_lines" SET "picked_qty" = -1 WHERE "vendor_return_id" = r;
				WHEN 'unknown reason' THEN UPDATE "vendor_return_lines" SET "reason_code" = 'smelly' WHERE "vendor_return_id" = r;
				WHEN 'line 0' THEN UPDATE "vendor_return_lines" SET "line_no" = 0 WHERE "vendor_return_id" = r;
				WHEN 'duplicate arm' THEN
					INSERT INTO "vendor_return_lines" ("id","tenant_id","vendor_return_id","line_no","sku_id","batch_id","grn_line_id","qty","picked_qty","reason_code","item_snapshot")
					VALUES (gen_random_uuid(), t, r, 2, c, NULL, NULL, 1000, NULL, 'damaged', '{}');
				WHEN 'duplicate line number' THEN
					INSERT INTO "vendor_return_lines" ("id","tenant_id","vendor_return_id","line_no","sku_id","batch_id","grn_line_id","qty","picked_qty","reason_code","item_snapshot")
					VALUES (gen_random_uuid(), t, r, 1, v, NULL, NULL, 1000, NULL, 'damaged', '{}');
			END CASE;
			RAISE EXCEPTION USING ERRCODE = 'P0105', MESSAGE = 'probe accepted';
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0105' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0105: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "vendor_returns" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "vendor_return_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0105: a probe row survived.';
	END IF;
END $$;
